function Icone({ tipo, tamanho = 40 }: { tipo: TipoIcone; tamanho?: number }) {
  const comum = { width: tamanho, height: tamanho, viewBox: "0 0 64 64", fill: "none", xmlns: "http://www.w3.org/2000/svg" };
  const stroke = "currentColor";
  const amarelo = "#facc15";

  if (tipo === "modulo") return <svg {...comum}><rect x="10" y="8" width="44" height="48" rx="3" fill="#1f2937" stroke={amarelo} strokeWidth="2"/><path d="M21 8v48M32 8v48M43 8v48M10 20h44M10 32h44M10 44h44" stroke="#93c5fd" strokeWidth="2"/></svg>;
  if (tipo === "inversor") return <svg {...comum}><rect x="9" y="12" width="46" height="40" rx="7" fill="#f4f4f5" stroke="#a1a1aa" strokeWidth="2"/><circle cx="32" cy="31" r="7" stroke="#111827" strokeWidth="2"/><path d="M26 31h12" stroke="#111827" strokeWidth="2"/><path d="M16 52v5M48 52v5" stroke="#111827" strokeWidth="3"/></svg>;
  if (tipo === "estrutura") return <svg {...comum}><path d="M8 43h48M12 36h40M18 28h36M12 43l8 11M50 43l-8 11M22 28l-6 15M48 28l4 15" stroke="#6b7280" strokeWidth="5" strokeLinecap="round"/></svg>;
  if (tipo === "cabos") return <svg {...comum}><path d="M10 28c4-11 15-11 19 0s15 11 19 0 8-11 12-2" stroke="#111827" strokeWidth="6" strokeLinecap="round"/><path d="M14 42c8-8 15-8 23 0s15 8 22 0" stroke="#dc2626" strokeWidth="6" strokeLinecap="round"/></svg>;
  if (tipo === "protecao") return <svg {...comum}><rect x="8" y="16" width="24" height="36" rx="3" fill="#f4f4f5" stroke="#6b7280" strokeWidth="2"/><rect x="36" y="14" width="20" height="40" rx="3" fill="#ef4444" stroke="#991b1b" strokeWidth="2"/><path d="M14 24h12M14 32h12M14 40h12" stroke="#111827" strokeWidth="3"/><path d="M42 23h8M42 31h8M42 39h8" stroke="white" strokeWidth="3"/></svg>;
  if (tipo === "ferramenta") return <svg {...comum}><path d="M15 49l18-18M26 14l24 24M19 12l9 9-7 7-9-9zM42 35l10 10-7 7-10-10z" stroke={stroke} strokeWidth="5" strokeLinecap="round" strokeLinejoin="round"/></svg>;
  if (tipo === "documento" || tipo === "analise") return <svg {...comum}><path d="M16 8h23l9 9v39H16z" stroke={stroke} strokeWidth="4"/><path d="M39 8v11h10M23 28h18M23 36h18M23 44h12" stroke={stroke} strokeWidth="3"/>{tipo === "analise" && <circle cx="46" cy="46" r="8" fill="white" stroke={stroke} strokeWidth="3"/>}</svg>;
  if (tipo === "energisa") return <svg {...comum}><path d="M18 8c13 6 16 16 8 26-4 5-6 10-4 20-11-7-14-16-8-26 5-8 8-12 4-20z" fill="#f97316"/><path d="M31 8c12 5 16 13 12 21-3 6-8 9-10 15 12-2 20-8 22-19-1-9-9-15-24-17z" fill="#0ea5e9"/></svg>;
  if (tipo === "monitoramento" || tipo === "grafico") return <svg {...comum}><rect x="12" y="8" width="40" height="48" rx="5" stroke={stroke} strokeWidth="4"/><path d="M20 44V33M28 44V25M36 44V30M44 44V18" stroke={amarelo} strokeWidth="5"/></svg>;
  if (tipo === "engrenagem") return <svg {...comum}><circle cx="32" cy="32" r="11" stroke={stroke} strokeWidth="6"/><path d="M32 7v10M32 47v10M7 32h10M47 32h10M14 14l7 7M43 43l7 7M50 14l-7 7M21 43l-7 7" stroke={stroke} strokeWidth="6" strokeLinecap="round"/></svg>;
  if (tipo === "suporte") return <svg {...comum}><path d="M12 34v-6a20 20 0 0140 0v6" stroke={stroke} strokeWidth="5"/><rect x="8" y="31" width="10" height="18" rx="4" fill={amarelo}/><rect x="46" y="31" width="10" height="18" rx="4" fill={amarelo}/><path d="M46 49c-2 6-7 8-15 8" stroke={stroke} strokeWidth="4"/></svg>;
  if (tipo === "aperto") return <svg {...comum}><path d="M8 29l13-12 11 9 11-9 13 12-16 19-8-7-8 7z" stroke="#111827" strokeWidth="4" fill="none"/><path d="M20 29l12 10 12-10" stroke="#111827" strokeWidth="4"/></svg>;
  if (tipo === "pessoa") return <svg {...comum}><circle cx="32" cy="20" r="10" fill="#111827"/><path d="M14 54c0-11 8-20 18-20s18 9 18 20" fill="#111827"/></svg>;
  if (tipo === "local") return <svg {...comum}><path d="M32 57s18-18 18-33a18 18 0 10-36 0c0 15 18 33 18 33z" fill="#111827"/><circle cx="32" cy="24" r="6" fill="white"/></svg>;
  if (tipo === "data") return <svg {...comum}><rect x="10" y="14" width="44" height="40" rx="5" fill="#111827"/><path d="M10 25h44M20 8v12M44 8v12" stroke="white" strokeWidth="4"/><path d="M20 34h6M30 34h6M40 34h6M20 44h6M30 44h6" stroke="white" strokeWidth="3"/></svg>;
  if (tipo === "raio") return <svg {...comum}><path d="M36 4L16 35h15l-3 25 20-34H34z" fill={amarelo}/></svg>;
  if (tipo === "cartao") return <svg {...comum}><rect x="5" y="13" width="54" height="38" rx="5" fill="#111827"/><rect x="5" y="22" width="54" height="8" fill="white"/><rect x="12" y="38" width="18" height="5" fill="#facc15"/></svg>;
  if (tipo === "banco") return <svg {...comum}><path d="M6 24L32 8l26 16H6zM12 27h7v22h-7zM28 27h8v22h-8zM45 27h7v22h-7zM7 53h50" fill="#111827" stroke="#111827" strokeWidth="3"/></svg>;
  if (tipo === "relogio") return <svg {...comum}><circle cx="32" cy="32" r="24" stroke="#111827" strokeWidth="5"/><path d="M32 17v17l12 7" stroke="#111827" strokeWidth="5" strokeLinecap="round"/></svg>;
  if (tipo === "folha") return <svg {...comum}><path d="M53 9C31 9 14 19 12 41c12 7 25 3 33-6 8-9 8-18 8-26z" fill="#22c55e"/><path d="M16 49c10-14 20-22 34-32" stroke="#166534" strokeWidth="4"/></svg>;
  if (tipo === "sol") return <svg {...comum}><circle cx="32" cy="32" r="13" stroke="#111827" strokeWidth="5"/><path d="M32 3v9M32 52v9M3 32h9M52 32h9M11 11l7 7M46 46l7 7M53 11l-7 7M18 46l-7 7" stroke="#111827" strokeWidth="5" strokeLinecap="round"/></svg>;
  return <svg {...comum}><circle cx="32" cy="32" r="24" fill={amarelo}/></svg>;
}
